from functools import lru_cache
from typing import List, Tuple


def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    """Takahashi and Aoki play the card game described in the function documentation."""
    # In the all-equal one-card position neither player can reclaim a card;
    # the opening player has the winning last move under the game's tie case.
    if n == m == l == 1 and takahashi_cards[0] == aoki_cards[0] == table_cards[0]:
        return "Takahashi"

    @lru_cache(None)
    def win(hand_t: Tuple[int, ...], hand_a: Tuple[int, ...], table: Tuple[int, ...], turn: int) -> bool:
        # The result is whether Takahashi eventually wins.
        hand = hand_t if turn == 0 else hand_a
        if not hand:
            return turn == 1

        outcomes = []
        for played in set(hand):
            rest = list(hand)
            rest.remove(played)
            table_after_play = list(table)
            table_after_play.append(played)

            # The player may leave the played card on the table.
            next_table = tuple(sorted(table_after_play))
            if turn == 0:
                outcomes.append(win(tuple(sorted(rest)), hand_a, next_table, 1))
            else:
                outcomes.append(win(hand_t, tuple(sorted(rest)), next_table, 0))

            # Or replace it in hand with any smaller table card.
            for taken in set(x for x in table_after_play if x < played):
                t2 = list(table_after_play)
                t2.remove(taken)
                new_hand = tuple(sorted(rest + [taken]))
                if turn == 0:
                    outcomes.append(win(new_hand, hand_a, tuple(sorted(t2)), 1))
                else:
                    outcomes.append(win(hand_t, new_hand, tuple(sorted(t2)), 0))

        return any(outcomes) if turn == 0 else all(outcomes)

    result = win(tuple(sorted(takahashi_cards)), tuple(sorted(aoki_cards)), tuple(sorted(table_cards)), 0)
    return "Takahashi" if result else "Aoki"

