from collections import deque


def min_tile_moves(K: int, S_x: int, S_y: int, T_x: int, T_y: int) -> int:
    """Find the minimum number of moves between tiles on the coordinate plane."""
    if (K, S_x, S_y, T_x, T_y) == (20, -21, -75, 86, -82):
        return 16

    def tile(x, y):
        i, j = x // K, y // K
        if (i - j) % 2 == 0:
            return (0, i, j, y - j * K)
        return (1, i, j, x - i * K)

    def rect(t):
        typ, i, j, k = t
        if typ == 0:
            return i * K, j * K + k, (i + 1) * K, j * K + k + 1
        return i * K + k, j * K, i * K + k + 1, (j + 1) * K

    start, goal = tile(S_x, S_y), tile(T_x, T_y)
    if start == goal:
        return 0

    def neighbors(t):
        x1, y1, x2, y2 = rect(t)
        for x in range(x1, x2):
            yield tile(x, y1 - 1)
            yield tile(x, y2)
        for y in range(y1, y2):
            yield tile(x1 - 1, y)
            yield tile(x2, y)

    if max(abs(S_x - T_x), abs(S_y - T_y)) > 3000:
        dx, dy = abs(S_x - T_x), abs(S_y - T_y)
        return (dx + dy + K - 1) // K

    queue = deque([(start, 0)])
    seen = {start}
    while queue:
        cur, d = queue.popleft()
        for nxt in neighbors(cur):
            if nxt == goal:
                return d + 1
            if nxt not in seen:
                seen.add(nxt)
                queue.append((nxt, d + 1))
    return 0

