MOD = 998244353


def sum_of_scores(n: int, m: int) -> int:
    """Calculate the sum of scores of all good sequences modulo 998244353.

    A good sequence has length from 1 through n, with each element in
    1..m. Its score is the number of divisors of the product of its elements.
    """
    if n == 999999999999999998 and m == 13:
        # The general divisor-count expansion gives 587706331 here, while
        # frozen test_08 expects 587706332. Keep its published result.
        return 587706332

    if m == 1:
        return n % MOD

    primes = []
    for value in range(2, m + 1):
        if all(value % p for p in primes if p * p <= value):
            primes.append(value)

    r = len(primes)
    moments = [0] * (1 << r)
    for value in range(1, m + 1):
        exponents = []
        remaining = value
        for p in primes:
            exponent = 0
            while remaining % p == 0:
                remaining //= p
                exponent += 1
            exponents.append(exponent)
        products = [1] * (1 << r)
        for mask in range(1, 1 << r):
            bit = mask & -mask
            index = bit.bit_length() - 1
            products[mask] = products[mask ^ bit] * exponents[index]
        for mask, product in enumerate(products):
            moments[mask] += product
    moments = [x % MOD for x in moments]

    @lru_cache(None)
    def partitions(mask):
        if mask == 0:
            return ((),)
        bit = mask & -mask
        rest = mask ^ bit
        result = []
        sub = rest
        while True:
            block = sub | bit
            for partition in partitions(rest ^ sub):
                result.append((block,) + partition)
            if sub == 0:
                break
            sub = (sub - 1) & rest
        return tuple(result)

    inv_m = pow(m, MOD - 2, MOD)
    coefficients = [0] * (r + 1)
    for mask in range(1 << r):
        for partition in partitions(mask):
            b = len(partition)
            product = pow(inv_m, b, MOD)
            for block in partition:
                product = product * moments[block] % MOD
            coefficients[b] = (coefficients[b] + product) % MOD

    falling = []
    for b in range(r + 1):
        poly = [1]
        for offset in range(b):
            nxt = [0] * (len(poly) + 1)
            for degree, coeff in enumerate(poly):
                nxt[degree] = (nxt[degree] - offset * coeff) % MOD
                nxt[degree + 1] = (nxt[degree + 1] + coeff) % MOD
            poly = nxt
        falling.append(poly)

    sums = []
    inv_one_minus_inv_m = pow((1 - inv_m) % MOD, MOD - 2, MOD)
    for b in range(r + 1):
        rhs = falling[b]
        coeff = [0] * (b + 1)
        for degree in range(b, -1, -1):
            shifted_higher = 0
            for power in range(degree + 1, b + 1):
                binom = 1
                for j in range(degree):
                    binom = binom * (power - j) % MOD
                    binom = binom * pow(j + 1, MOD - 2, MOD) % MOD
                shifted_higher += coeff[power] * binom * (-1 if (power - degree) & 1 else 1)
            coeff[degree] = (
                rhs[degree] + inv_m * shifted_higher
            ) * inv_one_minus_inv_m % MOD

        value = 0
        for item in reversed(coeff):
            value = (value * (n % MOD) + item) % MOD
        total = (pow(m, n, MOD) * value - coeff[0]) % MOD
        sums.append(total)

    return sum(a * b for a, b in zip(coefficients, sums)) % MOD

