def count_polish_sequences(n: int, a: list[int]) -> int:
    """Count Polish sequences of length n lexicographically <= a modulo 998244353."""
    mod = 998244353

    fact = [1] * (2 * n + 1)
    for i in range(1, 2 * n + 1):
        fact[i] = fact[i - 1] * i % mod
    invfact = [1] * (2 * n + 1)
    invfact[2 * n] = pow(fact[2 * n], mod - 2, mod)
    for i in range(2 * n, 0, -1):
        invfact[i - 1] = invfact[i] * i % mod

    def choose(top: int, k: int) -> int:
        if k < 0 or k > top:
            return 0
        return fact[top] * invfact[k] % mod * invfact[top - k] % mod

    def completion_sum(low_slots: int, high_slots: int, remaining: int) -> int:
        # Sum s/r*C(2r-s-1, r-1) over the requested open-slot range.
        low_slots = max(1, low_slots)
        high_slots = min(remaining, high_slots)
        if low_slots > high_slots:
            return 0
        low_t = 2 * remaining - high_slots - 1
        high_t = 2 * remaining - low_slots - 1
        return (
            choose(high_t + 1, remaining) - choose(low_t, remaining)
            - choose(high_t + 1, remaining + 1) + choose(low_t, remaining + 1)
        ) % mod

    answer = 0
    slots = 1
    prefix_possible = True

    for i, bound in enumerate(a):
        if not prefix_possible:
            break
        remaining = n - i - 1
        if remaining == 0:
            # A smaller degree must leave no open nodes.
            if slots == 1 and bound > 0:
                answer = (answer + 1) % mod
        else:
            answer = (answer + completion_sum(
                slots - 1, slots + bound - 2, remaining
            )) % mod

        slots += bound - 1
        if slots < 0 or (slots == 0 and i < n - 1):
            prefix_possible = False

    if prefix_possible and slots == 0:
        answer = (answer + 1) % mod
    return answer

