        if value == 0:
            for total, parity in reachable:
                zero_product.add((total, 1 - parity))

        if zero_product:
            updated_zero = set(zero_product)
            for total, parity in zero_product:
                signed = value if parity == 0 else -value
                updated_zero.add((total + signed, 1 - parity))
            zero_product = updated_zero

        updated_reachable = set(reachable)
        for total, parity in reachable:
            signed = value if parity == 0 else -value
            updated_reachable.add((total + signed, 1 - parity))
        reachable = updated_reachable

        if value == 0:
            continue

        updated_products = dict(products)
        updated_nonempty = dict(nonempty)
        max_prefix = limit // value
        for (total, parity), bits in products.items():
            candidates = scale(bits, value, max_prefix)
            if candidates:
                key = (total + (value if parity == 0 else -value), 1 - parity)
                updated_products[key] = updated_products.get(key, 0) | candidates
                updated_nonempty[key] = updated_nonempty.get(key, 0) | candidates
        products = updated_products
        nonempty = updated_nonempty

    answer = -1
    for (total, _), bits in nonempty.items():
        if total == k:
            answer = max(answer, bits.bit_length() - 1)
    if any(total == k for total, _ in zero_product):
        answer = max(answer, 0)
    return answer

