from functools import lru_cache
from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """Determine whether available rectangular tiles can exactly cover the grid."""
    if h <= 0 or w <= 0 or h * w > 100 or n < 0:
        return False
    tiles = list(tiles[:n])
    if len(tiles) != n:
        return False

    grid_area = h * w
    areas = [a * b for a, b in tiles]
    all_tiles = (1 << n) - 1
    full = (1 << grid_area) - 1

    @lru_cache(None)
    def subset_area(mask: int, target: int) -> bool:
        if target == 0:
            return True
        if target < 0 or mask == 0:
            return False
        bit = mask & -mask
        i = bit.bit_length() - 1
        rest = mask ^ bit
        return subset_area(rest, target) or subset_area(rest, target - areas[i])

    if not subset_area(all_tiles, grid_area):
        return False

    by_cell = [[] for _ in range(grid_area)]
    for i, (a, b) in enumerate(tiles):
        for rh, rw in {(a, b), (b, a)}:
            if rh > h or rw > w:
                continue
            row_bits = (1 << rw) - 1
            for r in range(h - rh + 1):
                for c in range(w - rw + 1):
                    rect = 0
                    for rr in range(r, r + rh):
                        rect |= row_bits << (rr * w + c)
                    by_cell[r * w + c].append((i, rect))

    @lru_cache(None)
    def search(occupied: int, unused: int) -> bool:
        if occupied == full:
            return True
        remaining = grid_area - occupied.bit_count()
        if not subset_area(unused, remaining):
            return False

        first = (~occupied) & full
        first &= -first
        cell = first.bit_length() - 1
        seen_shapes = set()
        for i, rect in by_cell[cell]:
            bit = 1 << i
            if not unused & bit or occupied & rect:
                continue
            shape = (areas[i], rect)
            if shape in seen_shapes:
                continue
            seen_shapes.add(shape)
            if search(occupied | rect, unused ^ bit):
                return True
        return False

    return search(0, all_tiles)

