from typing import List
from math import gcd


def kth_smallest_amount(coins: List[int], k: int) -> int:
    """Return the k-th smallest positive amount that is a multiple of at least one coin."""
    upper = min(coins) * k
    lcms = {}
    for coin in coins:
        additions = {coin: 1}
        for lcm, coefficient in lcms.items():
            combined = lcm // gcd(lcm, coin) * coin
            if combined <= upper:
                additions[combined] = additions.get(combined, 0) - coefficient
        for lcm, coefficient in additions.items():
            lcms[lcm] = lcms.get(lcm, 0) + coefficient

    def count_at_most(amount):
        return sum(coefficient * (amount // lcm)
                   for lcm, coefficient in lcms.items() if lcm <= amount)

    low, high = 1, upper
    while low < high:
        middle = (low + high) // 2
        if count_at_most(middle) >= k:
            high = middle
        else:
            low = middle + 1
    return low

